# Topic assignment uses explicit English word lists, not guessed translations.
lookup = {}
for topic, text in TOPICS.items():
    for word in text.split():
        lookup.setdefault(word.lower(), topic)

source = Path(sys.argv[1])
rows = {}
with source.open(encoding='utf-8-sig', newline='') as file:
    for row in csv.DictReader(file):
        word = row['word']
        if re.fullmatch(r'[a-z]+(?:-[a-z]+)?', word) and row['phonetic'] and row['translation']:
            rows[word] = row

def number(value):
    try: return int(value)
    except (ValueError, TypeError): return 0

def rank(row):
    frq, bnc = number(row['frq']), number(row['bnc'])
    if frq > 0: return frq
    if bnc > 0: return 50000 + bnc
    return 500000 - number(row['collins']) * 1000 - number(row['oxford']) * 100

def clean_translation(value):
    value = value.replace('\\r\\n', '\n').replace('\\n', '\n').replace('\\r', '\n')
    lines = [line.strip() for line in value.splitlines() if line.strip()]
    # Retain general definitions; specialist-tagged lines remain available in the source.
    common = [line for line in lines if not line.startswith('[')]
    return '\n'.join((common or lines)[:4])

def phonetic(value):
    return '/' + value.strip('/[] ').replace("'", 'ˈ').replace(':', 'ː').replace('ә', 'ə').replace('ɡ', 'g') + '/'

seed_text = (ROOT/'app.js').read_text().split('const seed = [',1)[1].split('\n];',1)[0]
seed_words = set(re.findall(r"^  \['([^']+)'", seed_text, re.M))
entries = {}
with (ROOT/'data/scenarios.tsv').open(encoding='utf-8', newline='') as file:
    for row in csv.DictReader(file, delimiter='\t'):
        word = row['word']
        is_phrase = ' ' in word or word.endswith(('.', '?', '!'))
        entries[word.lower()] = {
            'id': 'scene-' + hashlib.sha256(word.lower().encode()).hexdigest()[:12],
            'word': word, 'ipa': row['ipa'], 'pos': 'phr.' if is_phrase else 'n.',
            'meaning': row['meaning'], 'example': row['example'], 'exampleZh': row['exampleZh'],
            'category': row['category'], 'level': 'practical', 'source': 'original',
            'ipaNote': '美式音标' if row['ipa'] else '整句播放美式发音',
        }
        if word == 'in-network': entries[word.lower()]['pos'] = 'adj.'

# Common inflections and contractions are not reliably frequency-ranked by the source.
with (ROOT/'data/foundation.tsv').open(encoding='utf-8', newline='') as file:
    for row in csv.DictReader(file, delimiter='\t'):
        entries[row['word'].lower()] = {**row, 'id':'basic-'+hashlib.sha256(row['word'].lower().encode()).hexdigest()[:12],
                                      'category':'general','level':'core','source':'original','ipaNote':'美式音标'}
foundation_count = sum(w['level']=='core' for w in entries.values())

# Override a few very common entries whose source definitions are too specialized.
overrides = {
'a': ('/ə; eɪ/', 'art.', '一个；一位（用于以辅音音素开头的单数可数名词前）'),
'an': ('/ən; æn/', 'art.', '一个；一位（用于以元音音素开头的单数可数名词前）'),
'the': ('/ðə; ðiː/', 'art.', '这；那（表示特指或双方已知的人或事物）'),
'color': ('/ˈkʌlər/', 'n./v.', '颜色；给……着色（美式拼写，英式为 colour）'),
'schedule': ('/ˈskedʒuːl/', 'n./v.', '日程；时间表；安排；预定'),
'apartment': ('/əˈpɑːrtmənt/', 'n.', '公寓；一套住房'),
'gas': ('/gæs/', 'n.', '气体；燃气；汽油（美式口语）'),
'check': ('/tʃek/', 'n./v.', '检查；核对；支票；餐馆账单（美式）'),
'bill': ('/bɪl/', 'n.', '账单；纸币；法案；鸟喙'),
'practice': ('/ˈpræktɪs/', 'n./v.', '练习；实践；惯例；执业（美式拼写，动词也用 practice）'),
}
# Prioritize explicit scene words even when their frequency is low.
candidates = sorted(rows.values(), key=lambda r: (0 if r['word'] in lookup else 1, rank(r), r['word']))
selected = []
for row in candidates:
    word = row['word']
    if word in seed_words or word.lower() in entries: continue
    if rank(row) >= 500000 and word not in lookup: continue
    selected.append(row)
    if len(selected) + len(entries) >= 10000: break
frequency_order = sorted(selected, key=lambda r: (rank(r), r['word']))
frequency_positions = {r['word']:i for i,r in enumerate(frequency_order)}
for row in selected:
    word = row['word']
    meaning = clean_translation(row['translation'])
    match = re.match(r'^(pron\.|prep\.|conj\.|interj\.|int\.|num\.|art\.|adv\.|adj\.|vt\.|vi\.|n\.|v\.|a\.)\s*', meaning)
    pos = match.group(1) if match else ''
    if match: meaning = meaning[match.end():]
    if pos == 'a.': pos = 'adj.'
    ipa = phonetic(row['phonetic'])
    note = '词典音标（以英式为主）；播放为美式'
    if word in overrides:
        ipa, pos, meaning = overrides[word]
        note = '美式音标'
    index = frequency_positions[word]
    entries[word] = {'id':'dict-'+word, 'word':word,'ipa':ipa,'pos':pos,'meaning':meaning,'example':'',
                     'category':lookup.get(word,'general'),'level':'core' if index<3000-foundation_count else 'extend' if index<6000-foundation_count else 'advanced',
                     'source':'ecdict','ipaNote':note,'frequency':number(row['frq']) or None}
# Keep original scenarios together, then topics and frequency, so adjacent map regions are useful.
ordered = list(entries.values())
scene_order = {t:i for i,t in enumerate(['work','housing','shopping','food','health','banking','services','travel','digital','social','daily','growth','nature','feeling','art','general'])}
ordered.sort(key=lambda w:(0 if w['source']=='original' else 1, scene_order.get(w['category'],99), {'core':0,'extend':1,'advanced':2,'practical':0}[w['level']], w.get('frequency') or 999999, w['word'].lower()))
assert len(ordered)==10000
assert len({w['id'] for w in ordered})==len(ordered)
assert len({w['word'].lower() for w in ordered})==len(ordered)
meta={'version':1,'built':'2026-09-27','total':len(ordered),'levels':dict(Counter(w['level'] for w in ordered)),
      'categories':dict(Counter(w['category'] for w in ordered)),
      'source':'https://github.com/skywind3000/ECDICT','sourceCommit':'bc015ed2e24a7abef49fc6dbbb7fe32c1dadaf8b',
      'sourceSha256':hashlib.sha256(source.read_bytes()).hexdigest(),
      'notes':'学习层级是本项目按来源词频和场景选词划分，不等同于 CEFR 或官方考试等级。词典音标以英式为主，播放优先使用 en-US 语音。'}
(ROOT/'data/vocabulary.js').write_text('/* ECDICT-derived data: MIT; see ECDICT-LICENSE.txt and SOURCES.md. */\nwindow.WORD_GARDEN_VOCABULARY = '+json.dumps(ordered,ensure_ascii=False,separators=(',',':'))+';\nwindow.WORD_GARDEN_META = '+json.dumps(meta,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
(ROOT/'data/vocabulary-meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(meta,ensure_ascii=False,indent=2))
